apiIntegrations.responseShape:
interface ChannelsResponse {
  items: Array<{
    id: string;
    snippet: {
      title: string;
      customUrl?: string;
      thumbnails: {
        default: { url: string; width: number; height: number };
        medium?: { url: string; width: number; height: number };
        high?: { url: string; width: number; height: number };
      };
    };
    statistics: {
      subscriberCount: string;  // returned as a stringified integer
      videoCount: string;
      viewCount: string;
      hiddenSubscriberCount?: boolean;
    };
  }>;
}

interface SearchResponse {
  items: Array<{
    id: { kind: string; videoId: string };
    snippet: {
      publishedAt: string; // ISO 8601
      channelId: string;
      title: string;
      description: string;
      thumbnails: {
        default: { url: string; width: number; height: number };
        medium: { url: string; width: number; height: number };
        high: { url: string; width: number; height: number };
      };
      channelTitle: string;
    };
  }>;
}

interface VideosResponse {
  items: Array<{
    id: string;
    statistics: {
      viewCount: string;
      likeCount?: string;
      commentCount?: string;
    };
    contentDetails: {
      duration: string; // ISO 8601 e.g. 'PT5M42S'
    };
  }>;
}
